-- Aplicar matching e inserir
WITH matched AS (
  SELECT DISTINCT ON (d.id)
    d.id AS deal_id, d.account_id, _src.product_id
  FROM _src
  JOIN deals d
    ON d.status = 'won'
    AND d.won_at >= '2025-01-01' AND d.won_at < '2026-01-01'
    AND LOWER(TRIM(d.title)) = LOWER(TRIM(_src.contact_name))
    AND ABS(d.value - _src.sale_value) < 1
  ORDER BY d.id, ABS(d.won_at::date - _src.sale_date)
)
INSERT INTO deal_field_values (account_id, deal_id, field_id, value_text)
SELECT account_id, deal_id, '033b91fb-3add-4c96-aec9-567fefbd0fb2', product_id
FROM matched
ON CONFLICT (deal_id, field_id) DO UPDATE SET value_text = EXCLUDED.value_text;

DROP TABLE _src;